    15	
    16	import java.time.LocalDate;
    17	import java.util.UUID;
    18	
    19	@Service
    20	@Transactional
    21	public class ReturnLoanService implements ReturnLoanUseCase {
    22	
    23	    private final LoadLoanPort loadLoanPort;
    24	    private final SaveLoanPort saveLoanPort;
    25	    private final LoadBookPort loadBookPort;
    26	    private final SaveBookPort saveBookPort;
    27	
    28	    public ReturnLoanService(LoadLoanPort loadLoanPort, SaveLoanPort saveLoanPort,
    29	                             LoadBookPort loadBookPort, SaveBookPort saveBookPort) {
    30	        this.loadLoanPort = loadLoanPort;
    31	        this.saveLoanPort = saveLoanPort;
    32	        this.loadBookPort = loadBookPort;
    33	        this.saveBookPort = saveBookPort;
    34	    }
    35	
    36	    @Override
    37	    public Loan returnLoan(UUID loanId) {
    38	        // 대출 행을 잠가 같은 대출의 동시 반납 요청이 직렬로 처리되게 한다 (중복 반납 방지)
    39	        Loan loan = loadLoanPort.loadLoanForUpdate(loanId)
    40	                .orElseThrow(() -> new LoanNotFoundException(loanId));
    41	        loan.markReturned(LocalDate.now());
    42	        Book book = loadBookPort.loadBook(loan.getBookId())
    43	                .orElseThrow(() -> new BookNotFoundException(loan.getBookId()));
    44	        book.setStatus(BookStatus.AVAILABLE);
    45	        saveBookPort.saveBook(book);
    46	        saveLoanPort.saveLoan(loan);
    47	        return loan;
    48	    }
    49	}
